			function fnImageClick(data) {
				comFileDownload2(data);
			}
			function comFileDownload2(fileName) {
        	  	WebSquare.net.download( "/jsp/download2.jsp?"
					+"&fileName="+encodeURIComponent(WebSquare.text.BASE64Encoder(fileName)), "", "post" );
          	}
			/**************************************************************************
			 * function    : custFileDownImgCol
			 * Description : grid cell에 다운로드 버튼 이미지 보여주기 (커스텀 포맷터 사용)
			 * Parameter   : data,formattedData,row,col (커스텀 포맷터 기본 인자값들)
			 * Return      : null
			 **************************************************************************/
			function custFileDownImgCol(data,formattedData,row,col){
			
				// 스트링 값을 읽어 파일다운 버튼 이미지 생성				 
				var str = "";			
				
				if (data.length > 0){				
					// 이미지 태그 생성
					str = str + '<img src="/images/btn/allfile.gif" style="cursor:pointer;"' + ' title="" onclick="fnImageClick(\''+data+'\');"/>';
				}
				
				return str;
			}
			
			
			/**************************************************************************
			 * function    : getExistMaxDate
			 * Description : 신용등급 속보 조회
			 * Parameter   : null
			 * Return      : null
			 **************************************************************************/
			function getExistMaxDate(){
				
				var BISCdtRnkHotDTO = WebSquare.xml.indent(getInstanceNode("BISCdtRnkHotDTO"));
		       	
		      callProFrameProcess("BIS-KOFIABOND","BISCdtRnkHotSrchSO","getExistMaxDate",BISCdtRnkHotDTO,"respDate");		
			}       		
			
			/**************************************************************************
			 * function    : searchData
			 * Description : 신용등급 속보 조회
			 * Parameter   : null
			 * Return      : null
			 **************************************************************************/
        	function searchData() {
        		
        		WebSquare.ModelUtil.removeInstanceNode( "BISCdtRnkHotDTO" );
        		if ( isValidDate(standardDt1.getValue()) == false || isValidDate(standardDt2.getValue()) == false ) {
					showMsg("C_I029");
					return;
				}
				
				if  ( standardDt1.getValue() > standardDt2.getValue() ) {
					showMsg("C_I055");
					return;
				}
				
        		tabIndex = tabContents1.getSelectedTabIndex() + 1;
        		
        		if ( tabIndex >= "4" ) {
		
					if ( tabIndex == "7" ) {
						setValue("BISCdtRnkHotDTO/schField", 5); // 커버드본드 bondGb=5
					} else {
						setValue("BISCdtRnkHotDTO/schField", 3); // 종류 (선택 탭)
						setValue("BISCdtRnkHotDTO/val1", tabIndex - 4);
					}
					
        		} else if ( tabIndex == "3" ) {
        			setValue("BISCdtRnkHotDTO/schField", 4); // 종류 (선택 탭)
        		} else {
        			setValue("BISCdtRnkHotDTO/schField", tabIndex); // 종류 (선택 탭)
        		}
        		
        		setValue("BISCdtRnkHotDTO/creditEstCd", radio1.getValue()); // 신용평가사
        		setValue("BISCdtRnkHotDTO/companyNm", input2.getValue()); // 발행사 
        		
//        		if ( radio2.getValue() == 2 ) {
        			setValue("BISCdtRnkHotDTO/schData", radio2.getValue());
//        		}
        		
        		setValue("BISCdtRnkHotDTO/standardDt1", standardDt1.getValue()); //조회시작일
        		setValue("BISCdtRnkHotDTO/standardDt2", standardDt2.getValue()); //조회종료일
        		//setValue("BISCdtRnkHotDTO/creditExtCd", radio2.getValue()); //조회범위 
        				
		        var BISCdtRnkHotDTO =  {"BISCdtRnkHotDTO":{}};
			
		       	callProFrameSync("BIS-KOFIABOND", "BISCdtRnkHotSrchSO","select", BISCdtRnkHotDTO ,"BISCdtRnkHotDTO","resp");
				
        	}
        	

