            /**************************************************************************
             * function    : excelDownLoad
             * Description : 그리드의 내용을 엑셀로 다운로드
             * Parameter   : null
             * Return      : null
             **************************************************************************/
            function excelDownLoad(removeCol) {
            	switch ( tabContents1.getSelectedTabIndex() ) {
            		case 0:
            			saveExcelDown(grdMain, divisionNm, "1", true, false, removeCol);
            			break;
            		case 1:
            			saveExcelDown(grdMain2, divisionNm, "1", true, false, removeCol);
            			break;
            		case 2:
            			saveExcelDown(grdMain3, divisionNm, "1", true, false, removeCol);
            			break;
            		case 3:
            			saveExcelDown(grdMain4, divisionNm, "1", true, false, removeCol);
            			break;
            		case 4:
            			saveExcelDown(grdMain5, divisionNm, "1", true, false, removeCol);
            			break;
            		case 5:
            			saveExcelDown(grdMain6, divisionNm, "1", true, false, removeCol);
            			break;
					case 6:
            			saveExcelDown(grdMain7, divisionNm, "1", true, false, removeCol);
            			break;
            	}
            }
			
